    "localFixedCode": "using System;
using System.IO;
using System.Collections.Generic;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine.SceneManagement;
using NfsMwRemaster.Driving;

namespace Unity.AI.Assistant.Agent.Dynamic.Extension.Editor
{
    internal class CommandScript : IRunCommand
    {
        [Serializable]
        private class Placement
        {
            public int sourceOffset, prototype;
            public string name;
            public float[] worldPosition;
            public float rotation, widthScale, heightScale;
        }

        [Serializable]
        private class Prototype
        {
            public string name;
            public float[] anchor, boundsMin, boundsMax;
        }

        [Serializable]
        private class Manifest
        {
            public Placement[] instances;
            public Prototype[] prototypes;
        }

        public void Execute(ExecutionResult result)
        {
            var scene = SceneManager.GetActiveScene();
            if (scene.path != "Assets/NfsMw/Scenes/World/RockportMap.unity")
                throw new IOException("Open RockportMap");
            const string rootName = "Rockport Breakable Trees";
            GameObject root = null;
            foreach (var candidate in scene.GetRootGameObjects())
                if (candidate.name == rootName)
                    root = candidate;
            if (root)
                throw new IOException("Breakable tree root already exists; inspect before replacing authored components.");
            var manifest = JsonUtility.FromJson<Manifest>(File.ReadAllText("Art/RockportTrees/Source/terrain-trees.json"));
            root = new GameObject(rootName);
            result.RegisterObjectCreation(root);
            var world = root.AddComponent<DestructionWorld>();
            int removed = 0, created = 0;
            var ids = new HashSet<int>();
            foreach (var sceneRoot in scene.GetRootGameObjects())
            {
                if (sceneRoot.name != "Rockport Generated Terrain - 1m Heightmap" && sceneRoot.name != "Rockport Trees - Terrain Openings")
                    continue;
                foreach (var terrain in sceneRoot.GetComponentsInChildren<Terrain>(true))
                {
                    var data = terrain.terrainData;
                    var prototypes = data.treePrototypes;
                    var kept = new List<TreeInstance>();
                    foreach (var tree in data.treeInstances)
                    {
                        if (prototypes[tree.prototypeIndex].prefab.name.Contains("XO_CT_CAMPUSSMACKTREE"))
                            removed++;
                        else
                            kept.Add(tree);
                    }

                    data.SetTreeInstances(kept.ToArray(), false);
                    EditorUtility.SetDirty(data);
                    terrain.Flush();
                }
            }

            foreach (var placement in manifest.instances)
            {
                if (!placement.name.StartsWith("XO_CT_CAMPUSSMACKTREE", StringComparison.Ordinal))
                    continue;
                if (!ids.Add(placement.sourceOffset))
                    throw new IOException("Duplicate source tree");
                var proto = manifest.prototypes[placement.prototype];
                var prefab = AssetDatabase.LoadAssetAtPath<GameObject>("Assets/NfsMw/Content/World/Maps/Rockport/Trees/Prefabs/" + proto.name + ".prefab");
                if (!prefab)
                    throw new IOException("Missing source tree prefab");
                var obj = new GameObject(placement.name + "__" + placement.sourceOffset);
                obj.transform.SetParent(root.transform, false);
                obj.transform.position = new Vector3(placement.worldPosition[0], placement.worldPosition[1], placement.worldPosition[2]);
                obj.transform.rotation = Quaternion.Euler(0, placement.rotation * Mathf.Rad2Deg, 0);
                obj.transform.localScale = new Vector3(placement.widthScale, placement.heightScale, placement.widthScale);
                var visual = (GameObject)PrefabUtility.InstantiatePrefab(prefab, obj.transform);
                visual.name = "Original tree geometry";
                var body = obj.AddComponent<Rigidbody>();
                body.isKinematic = true;
                body.collisionDetectionMode = CollisionDetectionMode.ContinuousSpeculative;
                body.interpolation = RigidbodyInterpolation.Interpolate;
                var trunk = obj.AddComponent<CapsuleCollider>();
                float height = proto.boundsMax[1] - proto.boundsMin[1];
                trunk.height = height;
                trunk.radius = placement.name.Contains("SMACKTREEB") ? .11f : .08f;
                trunk.center = new Vector3(-proto.anchor[0], height * .5f, -proto.anchor[2]);
                float volume = Mathf.PI * trunk.radius * trunk.radius * height * placement.widthScale * placement.widthScale * placement.heightScale;
                body.mass = Mathf.Max(8, volume * 650);
                body.centerOfMass = trunk.center;
                obj.AddComponent<DestructibleProp>().ConfigureWholeBody("rockport.tree." + placement.sourceOffset, world, visual, new Collider[]{trunk}, body, SensorySurface.Wood);
                obj.AddComponent<OceanBuoyantBody>().Configure(null, new Bounds(trunk.center, new Vector3(trunk.radius * 2, height, trunk.radius * 2)), volume);
                created++;
            }

            if (created != 481 || removed != created)
                throw new IOException("Breakable tree promotion mismatch: " + created + " / " + removed);
            AssetDatabase.SaveAssets();
            EditorSceneManager.MarkSceneDirty(scene);
            EditorSceneManager.SaveScene(scene);
            Directory.CreateDirectory("Art/RockportTrees/Source");
            string json = "{\"status\":\"PASS\",\"breakableTrees\":" + created + ",\"removedTerrainInstances\":" + removed + ",\"remainingTerrainInstances\":8946,\"sourceSelection\":\"XO_CT_CAMPUSSMACKTREE and XO_CT_CAMPUSSMACKTREEB; matching original DMG and FRAG solids prove authored breakable families\",\"physicalBehavior\":\"Existing DestructibleProp WholeBody: trunk collider, kinematic until vehicle impact, dynamic fall and ocean buoyancy; source fragmentation not recreated\"}";
            File.WriteAllText("Art/RockportTrees/Source/breakable-tree-import.json", json);
            result.Log(json);
        }
    }

    [Serializable]
    private class Placement
    {
        public int sourceOffset, prototype;
        public string name;
        public float[] worldPosition;
        public float rotation, widthScale, heightScale;
    }

    [Serializable]
    private class Prototype
    {
        public string name;
        public float[] anchor, boundsMin, boundsMax;
    }

    [Serializable]
    private class Manifest
    {
        public Placement[] instances;
        public Prototype[] prototypes;
    }
}"
